"use client";

import { useCallback, useEffect, useRef, useState } from "react";

import Link from "next/link";

import { Frame } from "./Frame";
import { Price } from "./Price";
import { useCart } from "./cart-context";
import { isAvailable, type Product } from "@/lib/domain/types";

/**
 * Quick view.
 *
 * A grid of unique single pieces is browsed by comparison — a shopper opens
 * four sarees, decides between them, and buys one. Making each of those a full
 * page load and a back-navigation loses the comparison every time. Quick view
 * answers "what is this, and can I have it" without leaving the grid; anything
 * more than that (the narrative, the provenance, the full shot template) stays
 * on the PDP, which the modal links to rather than reproducing.
 *
 * Deliberately NOT a second buy funnel: it shares the cart context with the
 * PDP, so a piece added here lands in the same drawer, and the sold-out case
 * sends people to the PDP's notify form rather than growing a copy of it.
 */
export function QuickView({ product }: { product: Product }) {
  const [open, setOpen] = useState(false);

  return (
    <>
      <button
        type="button"
        // Centred in the frame rather than a bar along the bottom edge, where
        // it crowded the badge and the wishlist heart.
        //
        // z-10 clears the card's stretched link, which otherwise covers the
        // whole image and would swallow this click.
        className="eyebrow absolute top-1/2 left-1/2 z-10 -translate-x-1/2 -translate-y-1/2 bg-bg/92 px-6 py-3 text-ink opacity-0 transition-opacity duration-200 hover:bg-bg focus-visible:opacity-100 group-hover:opacity-100"
        onClick={(event) => {
          event.preventDefault();
          setOpen(true);
        }}
      >
        Quick view
      </button>
      {open ? (
        <QuickViewModal product={product} onClose={() => setOpen(false)} />
      ) : null}
    </>
  );
}

function QuickViewModal({
  product,
  onClose,
}: {
  product: Product;
  onClose: () => void;
}) {
  const closeRef = useRef<HTMLButtonElement>(null);
  const previousFocusRef = useRef<HTMLElement | null>(null);
  const { add } = useCart();

  const [primary, secondary] = product.images;
  const available = isAvailable(product);

  const close = useCallback(() => onClose(), [onClose]);

  // Same modal contract as the search overlay: remember focus, lock the page
  // behind it, hand focus back on the way out.
  useEffect(() => {
    previousFocusRef.current = document.activeElement as HTMLElement | null;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const focusTimer = setTimeout(() => closeRef.current?.focus(), 0);

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") close();
    };
    document.addEventListener("keydown", onKeyDown);

    return () => {
      clearTimeout(focusTimer);
      document.removeEventListener("keydown", onKeyDown);
      document.body.style.overflow = previousOverflow;
      previousFocusRef.current?.focus();
    };
  }, [close]);

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-ink/40 p-4"
      onClick={(event) => {
        if (event.target === event.currentTarget) close();
      }}
    >
      <div
        role="dialog"
        aria-modal="true"
        aria-label={`${product.poeticName} — quick view`}
        className="relative max-h-[88vh] w-full max-w-4xl overflow-y-auto bg-bg"
      >
        <button
          ref={closeRef}
          type="button"
          onClick={close}
          aria-label="Close quick view"
          className="absolute top-3 right-3 z-10 bg-bg/90 px-3 py-2 text-ink"
        >
          <span aria-hidden className="text-lg leading-none">
            &times;
          </span>
        </button>

        <div className="grid gap-6 md:grid-cols-[minmax(0,1fr)_minmax(0,1.1fr)] md:gap-10">
          {/* One frame, not a gallery. The full shot template is the PDP's
              job — a carousel here would be a page pretending to be a modal. */}
          <div className="md:py-6 md:pl-6">
            {primary ? (
              <Frame
                image={primary}
                colourSlug={product.colourFamily}
                sizes="(min-width: 768px) 380px, 90vw"
              />
            ) : null}
          </div>

          <div className="px-6 pb-6 md:py-8 md:pr-8 md:pl-0">
            <h2 className="font-display text-h3 text-ink">
              {product.poeticName}
            </h2>
            <p className="text-caption mt-1.5 text-ink-muted">{product.title}</p>
            <p className="mt-4 text-ink">
              <Price value={product.price} />
            </p>

            <dl className="text-caption mt-6 border-t border-rule pt-5">
              <SpecRow label="Colour" value={product.spec.colour} />
              <SpecRow label="Technique" value={product.spec.technique} />
              <SpecRow label="Fabric" value={product.spec.fabric} />
            </dl>

            {available ? (
              <div className="mt-6">
                <p className="text-caption text-ink-body">
                  {product.inventoryQuantity === 1
                    ? "One piece, and only one."
                    : `${product.inventoryQuantity} available to order.`}
                </p>
                <p className="text-caption mt-1 text-ink-muted">
                  Dispatched in {product.dispatchLeadDays[0]}–
                  {product.dispatchLeadDays[1]} business days.
                </p>
                <button
                  type="button"
                  className="mt-4 w-full bg-ink px-6 py-4 text-bg transition-opacity hover:opacity-90"
                  onClick={() => {
                    add(
                      {
                        handle: product.handle,
                        title: product.title,
                        poeticName: product.poeticName,
                        sku: product.sku,
                        priceMinorUnits: product.price.minorUnits,
                        colourSlug: product.colourFamily,
                        alt: primary?.alt ?? product.title,
                        maxQuantity: product.inventoryQuantity,
                      },
                      1,
                    );
                    // The drawer opens on add and takes the screen. Two
                    // stacked overlays each holding a scroll lock is one too
                    // many, so this one steps aside.
                    close();
                  }}
                >
                  <span className="eyebrow">Add to cart</span>
                </button>
              </div>
            ) : (
              <div className="mt-6 border border-rule-strong p-5">
                <p className="font-display text-h4 text-ink">
                  This one has gone.
                </p>
                <p className="text-caption mt-2 text-ink-body">
                  {product.poeticName} was a single piece. Ask to be written to
                  when it is rewoven.
                </p>
                <Link
                  href={`/products/${product.handle}#notify`}
                  className="cta mt-4 inline-block"
                >
                  Tell me when it is rewoven
                </Link>
              </div>
            )}

            <Link
              href={`/products/${product.handle}`}
              className="eyebrow mt-6 inline-block border-b border-rule-strong pb-1 text-ink"
            >
              View full details
            </Link>

            {/* The second frame, small, as a hint that there is more to see on
                the page this links to. */}
            {secondary ? (
              <div className="mt-6 hidden w-20 md:block">
                <Frame
                  image={secondary}
                  colourSlug={product.colourFamily}
                  sizes="80px"
                />
              </div>
            ) : null}
          </div>
        </div>
      </div>
    </div>
  );
}

function SpecRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex gap-4 border-b border-rule py-2 last:border-0">
      <dt className="w-28 shrink-0 text-ink-muted">{label}</dt>
      <dd className="text-ink-body">{value}</dd>
    </div>
  );
}
